/*
  创建 zblog 数据库
  COLLATE=utf8_bin; COLLATE=utf8_general_ci
  utf8_general_ci -- 不区分大小写，默认
  utf8_bin -- 区分大小写
*/
DROP DATABASE /*!32312 IF EXISTS*/ `zblog`;
CREATE DATABASE /*!32312 IF NOT EXISTS*/ `zblog` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin */;

USE `zblog`;

/*Table structure for table `user` */
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `ID` BIGINT UNSIGNED NOT NULL,
  `USERNAME` VARCHAR(20) NOT NULL COMMENT '用户名，可用于登录',
  `PASSWORD` VARCHAR(200) DEFAULT NULL COMMENT '登录密码',
  `USER_TYPE` TINYINT NOT NULL COMMENT '用户类型: 0-系统用户;1-普通用户;2-管理员用户;3-测试用户;4-临时用户',
  `USER_STATUS` TINYINT NOT NULL COMMENT '用户状态: 0-正常;1-禁用;2-锁定',
  `NICKNAME` VARCHAR(50) NOT NULL COMMENT '昵称',
  `EMAIL` VARCHAR(100) DEFAULT NULL COMMENT '邮箱',
  `GENDER` TINYINT NOT NULL DEFAULT 3 COMMENT '性别: 1-男;2-女;3-隐藏',
  `SIGNATURE` VARCHAR(100) NOT NULL DEFAULT '' COMMENT '座右铭',
  `WEBSITE` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '个人网站',
  `HEAD_IMG_URL` VARCHAR(512) DEFAULT '' COMMENT '头像链接',
  `EXPIRE_TIME` DATETIME(3) DEFAULT NULL COMMENT '临时账户的用户过期时间',
  `CHANGE_PASSWORD_TIME` DATETIME(3) DEFAULT NULL COMMENT '密码修改时间',
  `PASSWORD_EXPIRE_TIME` DATETIME(3) DEFAULT NULL COMMENT '密码到期时间',
  `LOGIN_ERROR_COUNT` TINYINT DEFAULT 0 COMMENT '登录失败次数',
  `LOCKED_EXPIRE_TIME` DATETIME(3) DEFAULT NULL COMMENT '用户锁定到期时间',
  `SUCCESS_LOGIN_TIME` DATETIME(3) DEFAULT NULL COMMENT '成功登录时间',
  `DELETED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `CREATE_USER` BIGINT NOT NULL COMMENT '创建用户',
  `CREATE_TIME` CHAR(19) NOT NULL COMMENT '创建时间',
  `UPDATE_USER` BIGINT DEFAULT NULL COMMENT '更新用户',
  `UPDATE_TIME` CHAR(19) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `uk_user_username` (`USERNAME`),
  UNIQUE KEY `uk_user_nickname` (`NICKNAME`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC COMMENT='用户表';

CREATE INDEX idx_user_username_deleted ON user(`USERNAME`, `DELETED`);
CREATE INDEX idx_user_deleted_type_status ON user(`DELETED`, `USER_TYPE`, `USER_STATUS`);
CREATE INDEX idx_user_successLogin ON user(`SUCCESS_LOGIN_TIME` DESC);

