/*Table structure for table `user_pass_log` */
DROP TABLE IF EXISTS `user_pass_log`;
CREATE TABLE `user_pass_log` (
  `ID` BIGINT UNSIGNED NOT NULL,
  `USER_ID` BIGINT NOT NULL COMMENT '用户ID',
  `PASSWORD` VARCHAR(200) NOT NULL COMMENT '历史密码',
  `CHANGE_PASSWORD_TIME` DATETIME(3) DEFAULT NULL COMMENT '密码修改时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=INNODB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='用户密码更新记录表';

CREATE INDEX idx_upl_uid_time ON user_pass_log (`USER_ID`, `CHANGE_PASSWORD_TIME` DESC);

/*Table structure for table `user_login_log` */
DROP TABLE IF EXISTS `user_login_log`;
CREATE TABLE `user_login_log` (
  `ID` BIGINT UNSIGNED NOT NULL,
  `USER_ID` BIGINT NOT NULL COMMENT '用户ID',
  `LOGIN_TIME` DATETIME(3) NOT NULL COMMENT '登录时间',
  `LOGIN_CHAN` CHAR(4) NOT NULL COMMENT '登录渠道',
  `LOGIN_TYPE` CHAR(4) NOT NULL COMMENT '登录类型',
  `LOGIN_IP` VARCHAR(15) NOT NULL COMMENT '登录IP',
  `LOGIN_ADDRESS` VARCHAR(255) DEFAULT NULL COMMENT '登录地址',
  `LOGIN_BROWSER` VARCHAR(255) COMMENT '浏览器',
  `LOGIN_BROWSER_VERSION` VARCHAR(255) COMMENT '浏览器版本',
  `LOGIN_PLATFORM` VARCHAR(255) COMMENT '平台',
  `USER_AGENT` VARCHAR(512) COMMENT '用户代理（保留字段）',
  `IS_SUCCESS` TINYINT NOT NULL COMMENT '登录是否成功',
  `REMARK` VARCHAR(255) COMMENT '备注',
  `CREATE_DATE` CHAR(10) NOT NULL COMMENT '创建日期',
  `CREATE_TIME` CHAR(19) NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='用户登录日志';

CREATE INDEX idx_ull_uid_success_time ON user_login_log (`USER_ID`, `IS_SUCCESS`, `LOGIN_TIME` DESC);
CREATE INDEX idx_ull_success_chan_type_time ON user_login_log (`IS_SUCCESS`, `LOGIN_CHAN`, `LOGIN_TYPE`, `LOGIN_TIME` DESC);

/*Table structure for table `role` */
DROP TABLE IF EXISTS `role`;
CREATE TABLE `role` (
  `ID` BIGINT UNSIGNED NOT NULL COMMENT '角色编号',
  `ROLE_NAME` VARCHAR(25) NOT NULL COMMENT '角色名称',
  `ROLE_CODE` VARCHAR(25) NOT NULL COMMENT '角色编码',
  `ROLE_DESC` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '角色描述',
  `ENABLED` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '是否启用',
  `DELETED` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `CREATE_USER` BIGINT NOT NULL COMMENT '创建用户',
  `CREATE_TIME` CHAR(19) NOT NULL COMMENT '创建时间',
  `UPDATE_USER` BIGINT DEFAULT NULL COMMENT '更新用户',
  `UPDATE_TIME` CHAR(19) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE KEY `uk_role_roleCode` (`ROLE_CODE`)
) ENGINE=INNODB ROW_FORMAT=DYNAMIC COMMENT='角色表';

