(8, '1.1.3.update3', '主题管理调整\n- 下线主题管理功能\n- 删除 base 主题', 8, 1, 1, '2021-05-11 02:21:52', NULL, NULL),
(9, '2.0.0', '第一个正式版本\n- 前端模板相对于 V1 版本进行全面更新\n- 新增日志监控功能\n- 引入全局异常处理机制\n- 集成 SLF4J 插件\n- 后端整体优化与排版调整\n- 修复若干 Bug', 9, 1, 1, '2021-05-25 02:43:21', NULL, NULL),
(10, '3.0.0', '后端功能优化与系统升级\n- 后端功能整体优化\n- 管理系统页面使用 layuiadmin1.7_std 优化\n- CKEditor4 升级至 CKEditor5\n- 部署服务器与数据库服务器分离\n- 集成 Redis 缓存机制\n- 删除在线用户统计功能\n- SSL 协议更新，采用阿里云 SSL', 10, 1, 1, '2021-08-07 20:05:36', NULL, NULL),
(11, '3.1.0', '文章功能与界面优化\n- 新增自动生成文章缩略图功能\n- Web 页面展示优化\n- 修复热门文章数量配置丢失问题', 11, 1, 1, '2021-08-11 05:35:33', NULL, NULL),
(12, '3.1.1', '工具集成与消息推送\n- 集成二维码自动生成工具\n- 集成飞鸽快信 API\n- 新增 OMS 消息自动推送功能\n- 修复查询字典列表失败问题', 12, 1, 1, '2021-08-19 18:13:15', NULL, NULL),
(13, '3.1.2', '文章展示优化\n- 修改文章内容图片展示方式\n- 关闭自动生成机制', 13, 1, 1, '2021-06-10 00:02:58', NULL, NULL),
(14, '3.2.0', '功能优化与 Bug 修复\n- 首页排版优化，抽取公共模板\n- 开发服务器监控功能\n- 移除 OMS 相关代码\n- 优化字典管理功能\n- 新增网站主题管理功能，支持动态修改前端主题\n- 修复字典子表编辑删除按钮无效问题', 14, 1, 1, '2022-06-20 16:03:51', NULL, NULL),
(15, '4.0.0', '前后端分离改造与开源\n- 完成前后端分离改造\n- 项目开源\n- 数据迁移', 15, 1, 1, '2023-02-21 01:42:28', NULL, NULL),
(16, '4.1.0', '性能优化与界面优化\n- 修复若干 Bug\n- 优化弹幕墙弹幕信息显示，屏蔽敏感词\n- 相册及说说页面排版优化', 16, 1, 1, '2023-04-22 02:12:14', NULL, NULL),
(17, '4.2.0', '架构重构与模块复用\n- 重构项目目录结构\n- 抽离并复用公共模块（序号生成、消息推送、文件上传等）\n- 提升整体可维护性', 17, 1, 1, '2023-07-12 20:21:15', NULL, NULL);

/*Table structure for table `file_storage` */
DROP TABLE IF EXISTS `file_storage`;
CREATE TABLE `file_storage` (
  `ID` BIGINT UNSIGNED NOT NULL COMMENT '物理文件ID',
  `FILENAME` VARCHAR(250) NOT NULL COMMENT '系统生成文件名（只有第一次上传才会生成）',
  `FILE_MD5` CHAR(32) NOT NULL COMMENT '文件MD5（唯一）',
  `FILE_SIZE` BIGINT NOT NULL COMMENT '文件大小',
  `FILE_ABSOLUTE_PATH` VARCHAR(500) NOT NULL COMMENT '存储绝对路径',
  `FILE_RELATIVE_PATH` VARCHAR(500) NOT NULL COMMENT '存储相对路径',
  `FILE_ACCESS_URL` VARCHAR(1000) NOT NULL COMMENT '访问地址',
  `FILE_TYPE` VARCHAR(50) NOT NULL COMMENT '文件类型',
  `UPLOAD_TYPE` TINYINT NOT NULL COMMENT '上传类型',
  `UPLOAD_USER` BIGINT NOT NULL COMMENT '上传用户',
  `UPLOAD_TIME` DATETIME NOT NULL COMMENT '上传时间',
  PRIMARY KEY (`ID`),
  KEY `IDX_FS_UPLOAD_TYPE` (`UPLOAD_TYPE`),
  UNIQUE KEY `UK_IDX_FS_FILE_MD5` (`FILE_MD5`, `UPLOAD_TYPE`)
) ENGINE=InnoDB COMMENT='物理文件存储表';

/*Table structure for table `file` */
DROP TABLE IF EXISTS `file`;
CREATE TABLE `file` (
  `ID` BIGINT UNSIGNED NOT NULL COMMENT '逻辑文件ID',
  `STORAGE_ID` BIGINT UNSIGNED NOT NULL COMMENT '物理文件ID',
  `ORIGINAL_FILENAME` VARCHAR(250) NOT NULL COMMENT '原始文件名',
  `CREATE_USER` BIGINT NOT NULL COMMENT '创建用户',
  `CREATE_TIME` DATETIME NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`ID`),
  KEY `IDX_STORAGE_ID` (`STORAGE_ID`)
) ENGINE=InnoDB COMMENT='逻辑文件表';

/*Table structure for table `file_relation` */
DROP TABLE IF EXISTS `file_relation`;
CREATE TABLE `file_relation` (
  `FILE_ID` BIGINT UNSIGNED NOT NULL COMMENT '逻辑文件ID',
  `BUSINESS_ID` BIGINT NOT NULL COMMENT '业务ID',
  `BUSINESS_TYPE` TINYINT NOT NULL COMMENT '业务类型',
  UNIQUE KEY `UK_FILE_BIZ` (`FILE_ID`, `BUSINESS_ID`)
  /*UNIQUE KEY `UK_FILE_BIZ` (`FILE_ID`, `BUSINESS_ID`, `BUSINESS_TYPE`) */
) ENGINE=InnoDB COMMENT='文件业务关联表';

-- ----------------------------
-- Table structure for audit_record
-- ----------------------------
DROP TABLE IF EXISTS `audit_record`;
CREATE TABLE `audit_record` (
  `ID` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `UID` VARCHAR(64) DEFAULT NULL COMMENT '用户ID',
  `OID` VARCHAR(64) DEFAULT NULL COMMENT '业务对象ID',
  `SCENE` VARCHAR(32) NOT NULL COMMENT '审核场景 COMMENT/MESSAGE/...',
  `ORIGINAL_CONTENT` TEXT COMMENT '原始内容',
  `FINAL_CONTENT` TEXT COMMENT '最终内容',
  `DECISION` VARCHAR(16) NOT NULL COMMENT '审核结果',
  `HIT_WORDS` JSON COMMENT '命中关键词',
  `REASON` VARCHAR(1024) COMMENT '审核原因',
  `TRACES` JSON COMMENT '处理器执行轨迹',
  `COST_MS` BIGINT DEFAULT 0 COMMENT '总耗时(ms)',
  `CREATE_TIME` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`ID`),
  KEY `idx_audit_record_uid` (`UID`),
  KEY `idx_audit_record_oid` (`OID`),
  KEY `idx_audit_record_scene` (`SCENE`),
  KEY `idx_audit_record_decision` (`DECISION`),
  KEY `idx_audit_record_create_time` (`CREATE_TIME`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='内容审核记录表';

-- ----------------------------
-- Table structure for sensitive_word
-- ----------------------------
DROP TABLE IF EXISTS `sensitive_word`;
CREATE TABLE `sensitive_word` (
  `ID` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `WORD` VARCHAR(255) NOT NULL COMMENT '敏感词',
  `TYPE` VARCHAR(50) DEFAULT 'DEFAULT' COMMENT '词类型',
  `LEVEL` TINYINT DEFAULT 1 COMMENT '风险等级：1-低 2-中 3-高',
  `STATUS` TINYINT DEFAULT 1 COMMENT '状态：1启用 0禁用',
  `REMARK` VARCHAR(200) DEFAULT NULL COMMENT '备注',
  `CREATE_USER` BIGINT NOT NULL COMMENT '创建用户',
  `CREATE_TIME` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UPDATE_USER` BIGINT DEFAULT NULL COMMENT '更新用户',
  `UPDATE_TIME` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  UNIQUE KEY `uk_sensitive_word` (`WORD`),
  KEY `idx_sensitive_word_status` (`STATUS`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='敏感词库表';

-- ----------------------------
-- Table structure for i18n_message
-- ----------------------------
DROP TABLE IF EXISTS `i18n_message`;
CREATE TABLE `i18n_message` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `code` VARCHAR(255) NOT NULL COMMENT '消息代码，建议带前缀标识类别',
  `locale` VARCHAR(20) NOT NULL COMMENT '语言标识，如 zh-CN、en-US',
  `message` VARCHAR(500) NOT NULL COMMENT '国际化文本内容',
  `type` VARCHAR(100) NOT NULL COMMENT '消息类型',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code_locale` (`code`, `locale`)
) ENGINE=InnoDB COMMENT='国际化消息表';

